const ROWS: Row[] = ROWS_1.concat(ROWS_2).concat(ROWS_3).concat(ROWS_4);

/**
 * Type decides discount category.
 *
 * It used to come from a per-category mapping table that was empty, so nothing
 * was discountable. Deriving it from the type is one rule instead of forty and
 * it is right by construction — a spare is priced like a spare whatever book it
 * belongs to.
 *
 * Declared before CATALOG, not after: a `const` is hoisted but not initialised,
 * so referencing it from the map below would throw on module evaluation and the
 * whole app would fail to mount.
 */
const DISCOUNT_BY_ROLE: Record<string, string> = {
  printer: 'system', printhead: 'system', warranty: 'system',
  consumable: 'consumables', ink: 'consumables',
  accessory: 'accessories', spare: 'accessories',
  service: 'system', promo: 'customs',
};

export const CATALOG: Item[] = ROWS.map(
  ([itemNo, description, technologyCode, itemRole, listPrice, model, classSource,
    attributes, category]) => ({
    itemNo,
    description,
    technologyCode,
    itemRole,
    listPrice,
    // Invented, like the price. Orbit standard cost in the real tool, and where
    // Orbit holds none the tool withholds margin rather than guess at it.
    stdCost: Math.round(listPrice * 0.52),
    model,
    classSource,
    discountCatCode: DISCOUNT_BY_ROLE[itemRole] ?? 'accessories',
    prodCat: technologyCode + '-' + itemRole.slice(0, 3).toUpperCase(),
    prodCatDesc: technologyCode + ' ' + itemRole,
    // The hierarchy's own word for what this part is: Stands, Conveyor, Brackets,
    // Scanner, Ribbon, Solvents. Empty where nothing said.
    category: category || null,
    uom: 'EA',
    isActive: !INACTIVE.has(itemNo),
    attributes,
  }),
);

